import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/cyclehire_w000.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute Self-Containment Index for each borough
boroughs = df['StartBorough'].unique()
self_containment_index = {}

for borough in boroughs:
    departures = len(df[df['StartBorough'] == borough])
    self_contained_trips = len(df[(df['StartBorough'] == borough) & (df['EndBorough'] == borough)])
    arrival_share = len(df[df['EndBorough'] == borough]) / len(df)
    expected_self_contained_trips = departures * arrival_share
    self_containment_index[borough] = self_contained_trips / expected_self_contained_trips

# Identify neighboring boroughs
neighborhoods = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Calculate Self-Containment Index for neighboring boroughs
neighbor_self_containment_index = {}
for borough, neighbors in neighborhoods.items():
    for neighbor in neighbors:
        neighbor_self_containment_index[neighbor] = self_containment_index.get(neighbor, 0)

# Determine HOT SPOT and COLD SPOT boroughs
hot_spots = []
cold_spots = []
for borough, index in self_containment_index.items():
    if index > 1.5 and all(self_containment_index.get(neighbor, 0) > 1.5 for neighbor in neighborhoods.get(borough, [])):
        hot_spots.append((borough, index))
    elif index < 0.5 and all(self_containment_index.get(neighbor, 0) < 0.5 for neighbor in neighborhoods.get(borough, [])):
        cold_spots.append((borough, index))

# Perform statistical analysis (optional)
np.random.seed(0)
p_values = {}
for borough, index in self_containment_index.items():
    if index > 1.5 or index < 0.5:
        permutations = 500
        test_statistic = index
        null_distribution = []
        for _ in range(permutations):
            shuffled_df = df.copy()
            shuffled_df['StartBorough'] = np.random.permutation(shuffled_df['StartBorough'])
            shuffled_departures = len(shuffled_df[shuffled_df['StartBorough'] == borough])
            shuffled_self_contained_trips = len(shuffled_df[(shuffled_df['StartBorough'] == borough) & (shuffled_df['EndBorough'] == borough)])
            shuffled_arrival_share = len(shuffled_df[shuffled_df['EndBorough'] == borough]) / len(shuffled_df)
            shuffled_expected_self_contained_trips = shuffled_departures * shuffled_arrival_share
            null_distribution.append(shuffled_self_contained_trips / shuffled_expected_self_contained_trips)
        p_values[borough] = np.mean([1 for value in null_distribution if value > test_statistic])

# Report results
data_points_used = len(df)
print(f'data_points_used = {data_points_used}')

if hot_spots or cold_spots:
    print('FINAL ANSWER: ', end='')
    for i, (borough, index) in enumerate(hot_spots + cold_spots):
        if i < len(hot_spots):
            print(f'{borough} (HH, statistical method={p_values.get(borough, 0)}), ', end='')
        else:
            print(f'{borough} (LL, statistical method={p_values.get(borough, 0)}), ', end='')
    print()
else:
    print('FINAL ANSWER: none')

import pandas as pd
import numpy as np

# Load data
data = pd.read_csv('chunks_csv/cyclehire_w000.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute Self-Containment Index for each borough
boroughs = data['StartBorough'].unique()
self_containment_index = {}

for borough in boroughs:
    departures = len(data[data['StartBorough'] == borough])
    self_contained_trips = len(data[(data['StartBorough'] == borough) & (data['EndBorough'] == borough)])
    arrival_share = len(data[data['EndBorough'] == borough]) / len(data)
    expected_self_contained_trips = departures * arrival_share
    self_containment_index[borough] = self_contained_trips / expected_self_contained_trips

# Identify neighboring boroughs
neighborhoods = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Calculate Self-Containment Index for neighboring boroughs
neighborhood_self_containment_index = {}
for borough, neighbors in neighborhoods.items():
    neighborhood_self_containment_index[borough] = {}
    for neighbor in neighbors:
        neighborhood_self_containment_index[borough][neighbor] = self_containment_index.get(neighbor, 0)

# Determine HOT SPOT and COLD SPOT boroughs
hot_spots = []
cold_spots = []
threshold = 1.5
for borough, index in self_containment_index.items():
    if index > threshold:
        is_hot_spot = True
        for neighbor, neighbor_index in neighborhood_self_containment_index[borough].items():
            if neighbor_index < threshold:
                is_hot_spot = False
                break
        if is_hot_spot:
            hot_spots.append((borough, index))
    elif index < 0.5:
        is_cold_spot = True
        for neighbor, neighbor_index in neighborhood_self_containment_index[borough].items():
            if neighbor_index > threshold:
                is_cold_spot = False
                break
        if is_cold_spot:
            cold_spots.append((borough, index))

# Perform statistical analysis (optional)
if len(hot_spots) > 0 or len(cold_spots) > 0:
    data_points_used = len(self_containment_index)
    print(f"data_points_used = {data_points_used}")

    for borough, index in hot_spots:
        print(f"FINAL ANSWER: {borough} (HH, test statistic = {index}, significance measure = {np.mean([self_containment_index.get(neighbor, 0) for neighbor in neighborhoods[borough]])})")

    for borough, index in cold_spots:
        print(f"FINAL ANSWER: {borough} (LL, test statistic = {index}, significance measure = {np.mean([self_containment_index.get(neighbor, 0) for neighbor in neighborhoods[borough]])})")
else:
    print("FINAL ANSWER: none")
